  try { const o = JSON.parse(s); return o && typeof o === 'object' ? o : {}; } catch { /* clipped: salvage below */ }
  const out = {};
  const re = /"([A-Za-z_][\w-]*)"\s*:\s*("(?:[^"\\]|\\.)*"?|-?\d+(?:\.\d+)?|true|false|null|\[[^\]]*\]?)/g;
