  if (/^memory\.profile\.set$/.test(n) && a.key) return 'Remembered your ' + esc(String(a.key).replace(/[._]+/g, ' '));
  if (/^memory\..*\.recall$/.test(n)) return a.query ? 'Recalled ' + quote(a.query) : 'Recalled memories';
