  if (n === 'os.fs.list' || n === 'os.fs.glob' || n === 'os.fs.trash') return 'folder';
  if (n === 'os.fs.write' || n === 'os.fs.edit' || n === 'os.fs.patch') return 'edit';
  if (n === 'os.fs.grep') return 'search';
