  TK.note = sc.kind === 'at' ? tkAtNote('the `at` time') : null;
  toast('Task scheduled', TK.msg + (TK.note ? ' — ' + TK.note : ''));
  TK.mode = 'list'; TK.form = null;
  await tasksRefresh();
