    const detail = await memBuildDetail(row);
    if (MEM.detailRowKey !== row.rowKey || MEM.mode !== 'detail') return;
    if (!detail) { MEM.mode = 'list'; MEM.lastError = 'memory detail unavailable for ' + row.rowKey; render(); return; }
