/* Any pull that lands — the wizard's, the composer's or this tab's — leaves the
   Local list out of date: mark it so, and read it now if the tab is on screen.
   Without this a model downloaded from the wizard kept its Download button
   here until the app was restarted. */
if (BR) {
  BR.onPull((ev) => {
    if (!ev || !ev.done || !ev.ok) return;
    const stale = () => { LLMP.lastRefreshedAt = null; if (llmVisible()) setTimeout(llmRefresh, 0); };
    /* A read already out may have listed the models before this one landed,
       and its finish would stamp the list fresh: mark it again after that. */
    if (LLMP.inflight) LLMP.inflight.then(stale, stale); else stale();
  });
}

/* The pull stream for the LLM tab's downloads, guarded by its own owner flag like the SEL/MP subscribers. */
if (BR) {
  BR.onPull((ev) => {
    if (!ev || !LLMP.pulling) return;
    if (ev.line) { LLMP.pullLog.push(ev.line); const box = document.getElementById('llm-pull-line'); if (box) box.textContent = ev.line; }
    if (ev.done) {
      const p = LLMP.pulling; LLMP.pulling = null;
      if (ev.ok) { LLMP.msg = {text:'local-llm: ' + p.id + ' installed'}; llmAfterPull(p); }
      else { LLMP.statusErr = ev.error || 'the download failed'; LLMHF.pendingMmproj = null; llmRepaint(); }
    }
  });
}

